import { Injectable, signal, inject, NgZone, OnDestroy } from '@angular/core';
import type { InstanceInfo } from '../models';
import { SseService } from './sse.service';
import { InstanceService } from './instance.service';

// Notification interface matching backend SSE payload
export interface InstanceNotification {
  instance_id: string;
  agent_id: string;
  name: string;
  status: 'COMPLETED' | 'ERROR' | 'TERMINATED' | 'FAILED';
  timestamp: string;
}

// Internal notification for UI
export interface Notification extends InstanceNotification {
  id: string;  // Use instance_id as id
  read: boolean;
}

// Agents that should NOT trigger notification sounds (visual notifications still shown)
const SOUND_EXCLUDED_AGENT_IDS = new Set(['kb-import', 'experiencer']);

// KB agent IDs - keep in sync with daemon/repositories/instance/repository.py (KB_AGENT_IDS)
const KB_AGENT_IDS = new Set(['experiencer', 'kb-importer']);

@Injectable({ providedIn: 'root' })
export class NotificationService implements OnDestroy {
  private readonly ngZone = inject(NgZone);
  private readonly sseService = inject(SseService);
  private readonly instanceService = inject(InstanceService);
  private readonly API_BASE = '/api';
  
  // Signals for reactive state
  readonly notifications = signal<Notification[]>([]);
  readonly unreadCount = signal<number>(0);
  
  // SSE connection
  private eventSource: EventSource | null = null;
  private reconnectAttempts = 0;
  private readonly MAX_RECONNECT_DELAY = 30000;
  
  // Audio
  private audio: HTMLAudioElement | null = null;
  private audioUnlocked = false;
  private unlockHandler: (() => void) | null = null;

  constructor() {
    this.initAudio();
    this.setupAudioUnlock();
    this.connect();
  }
  
  ngOnDestroy(): void {
    this.disconnect();
    if (this.unlockHandler) {
      document.removeEventListener('click', this.unlockHandler);
      document.removeEventListener('keydown', this.unlockHandler);
      this.unlockHandler = null;
    }
  }
  
  private initAudio(): void {
    // 3-note ascending chime (E5->A5->C#6) with bell harmonics, 1.5s, 16kHz mono
    const chimeBase64 = 'data:audio/wav;base64,';
    this.audio = new Audio(chimeBase64);
    this.audio.volume = 0.5;
  }

  private setupAudioUnlock(): void {
    const unlock = () => {
      if (this.audio && !this.audioUnlocked) {
        this.audio.play().then(() => {
          // Only remove listeners and cleanup on SUCCESS
          this.audioUnlocked = true;
          if (this.audio) {
            this.audio.pause();
            this.audio.currentTime = 0;
          }
          document.removeEventListener('click', unlock);
          document.removeEventListener('keydown', unlock);
          this.unlockHandler = null;
        }).catch(() => {
          // Keep listeners active for retry on next interaction
        });
      }
    };
    this.unlockHandler = unlock;
    document.addEventListener('click', unlock);
    document.addEventListener('keydown', unlock);
  }

  private playSound(): void {
    if (this.audio && this.audioUnlocked) {
      this.audio.currentTime = 0;
      this.audio.play().catch(() => {});
    }
  }
  
  connect(): void {
    if (this.eventSource) {
      return;
    }
    
    this.eventSource = new EventSource(`${this.API_BASE}/notifications/stream`);

    this.eventSource.onopen = () => {
      this.reconnectAttempts = 0;
    };
    
    this.eventSource.addEventListener('notification', (event: MessageEvent) => {
      this.ngZone.run(() => {
        try {
          const data: InstanceNotification = JSON.parse(event.data);
          this.addNotification(data);
        } catch {
          // Ignore parse errors
        }
      });
    });

    // Handle instance_created events for root instance tree updates
    this.eventSource.addEventListener('instance_created', (event: MessageEvent) => {
      this.ngZone.run(() => {
        try {
          const data = JSON.parse(event.data);
          // KB filtering: skip if KB agent and showKb is false
          const agentId = data.data?.agent_id as string;
          if (!this.instanceService.showKb() && KB_AGENT_IDS.has(agentId)) {
            return;
          }
          // Forward to SSE service signal so InstanceService.effect() picks it up
          const instanceData: InstanceInfo = {
            instance_id: data.data.instance_id as string,
            agent_id: agentId,
            parent_id: (data.data.parent_id as string) || null,
            status: data.data.status as InstanceInfo['status'],
            project_id: data.data.project_id as string | null,
            title: data.data.title as string | null,
            children: (data.data.children as string[]) || [],
            created_at: data.data.created_at as string,
            updated_at: data.data.created_at as string,
          };
          this.sseService.instanceCreatedQueue.update(q => [...q, instanceData]);
        } catch {
          // Ignore parse errors
        }
      });
    });

    this.eventSource.onerror = () => {
      this.ngZone.run(() => {
        this.disconnect();
        this.scheduleReconnect();
      });
    };
  }
  
  private scheduleReconnect(): void {
    const delay = Math.min(
      1000 * Math.pow(2, this.reconnectAttempts),
      this.MAX_RECONNECT_DELAY
    );
    this.reconnectAttempts++;
    
    setTimeout(() => {
      this.connect();
    }, delay);
  }
  
  disconnect(): void {
    if (this.eventSource) {
      this.eventSource.close();
      this.eventSource = null;
    }
  }
  
  private addNotification(notification: InstanceNotification): void {
    const newNotification: Notification = {
      ...notification,
      id: notification.instance_id,
      read: false,
    };

    this.notifications.update(list => {
      // Check if notification with same instance_id already exists
      const existingIndex = list.findIndex(n => n.instance_id === notification.instance_id);
      if (existingIndex !== -1) {
        // Replace existing notification instead of adding duplicate
        const updatedList = [...list];
        updatedList[existingIndex] = newNotification;
        return updatedList.slice(0, 50); // Keep last 50
      }
      // Add new notification
      return [newNotification, ...list].slice(0, 50); // Keep last 50
    });
    this.unreadCount.update(count => count + 1);
    if (!SOUND_EXCLUDED_AGENT_IDS.has(notification.agent_id)) {
      this.playSound();
    }
  }
  
  markAsRead(id: string): void {
    this.notifications.update(list =>
      list.map(n => (n.id === id ? { ...n, read: true } : n))
    );
    this.recalculateUnreadCount();
  }
  
  markAllAsRead(): void {
    this.notifications.update(list =>
      list.map(n => ({ ...n, read: true }))
    );
    this.unreadCount.set(0);
  }
  
  clearNotification(id: string): void {
    const wasUnread = this.notifications().find(n => n.id === id && !n.read);
    this.notifications.update(list => list.filter(n => n.id !== id));
    if (wasUnread) {
      this.recalculateUnreadCount();
    }
  }
  
  clearAll(): void {
    this.notifications.set([]);
    this.unreadCount.set(0);
  }
  
  private recalculateUnreadCount(): void {
    const count = this.notifications().filter(n => !n.read).length;
    this.unreadCount.set(count);
  }
}
